rule.sql:
SET
  @nowMs        = timestamp(),
  @day          = floor(@nowMs / 1000 / 86400),
  @thing        = topic(3),
  @transaction  = topic(4),
  @isStart      = (status = 'STARTED'),
  @isDone       = (status = 'DONE'),
  @isFail       = (status = 'ERROR'),
  @pk           = concat('Camera#', @thing)

SELECT
  @pk AS PK,
  concat('Rec#', @transaction) AS SK,

  @transaction   AS transactionId,
  status  AS status,
  @nowMs AS updatedAt,

  'Recs#ALL' AS allRecordingsPk,
  concat(cast(@nowMs as String), '#', @pk, '#', @transaction) AS allRecordingsSk,

  CASE @isStart WHEN true THEN targetBitrate END AS targetBitrate,
  CASE @isStart WHEN true THEN targetFps     END AS targetFps,

  CASE @isDone WHEN true THEN filename        END AS filename,
  CASE @isDone WHEN true THEN filesize        END AS filesize,
  CASE @isDone WHEN true THEN recordedSeconds END AS lengthSec,

  CASE @isFail WHEN true THEN errorCode END AS errorCode,
  CASE @isFail WHEN true THEN errorMessage END AS errorMessage,
  CASE @isFail WHEN true THEN errorOrigin END AS failedModule,
  CASE @isFail WHEN true THEN timestamp END AS timestamp

FROM 'yx/recordings/+/+/status'
WHERE
    @thing = clientid() AND status <> 'ONGOING'
